[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Merriweather:wght@400;700&display=swap" rel="stylesheet" />
  <style>
    /* ── Reset & base ───────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --red:       #C41E3A;
      --red-dark:  #A3192F;
      --red-light: #F5E6E9;
      --navy:      #1B3A5C;
      --navy-dark: #132C47;
      --white:     #FFFFFF;
      --gray-50:   #F8F9FA;
      --gray-100:  #F1F3F5;
      --gray-200:  #E9ECEF;
      --gray-400:  #ADB5BD;
      --gray-600:  #6C757D;
      --gray-800:  #343A40;
      --gray-900:  #212529;
      --radius:    6px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
      --shadow:    0 4px 16px rgba(0,0,0,.12);
      --shadow-lg: 0 8px 32px rgba(0,0,0,.18);
      --transition: 0.22s ease;
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', sans-serif;
      color: var(--gray-900);
      line-height: 1.6;
      background: var(--white);
    }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { cursor: pointer; font-family: inherit; }

    /* ── Utilities ──────────────────────────────────────────── */
    .container { max-width: 1180px; margin: 0 auto; padding: 0 24px; }
    .btn {
      display: inline-flex; align-items: center; justify-content: center;
      padding: 12px 28px; border-radius: var(--radius);
      font-size: 1rem; font-weight: 600; border: 2px solid transparent;
      transition: background var(--transition), color var(--transition),
                  border-color var(--transition), transform var(--transition);
      line-height: 1.2;
    }
    .btn:focus-visible { outline: 3px solid var(--red); outline-offset: 3px; }
    .btn-primary {
      background: var(--red); color: var(--white);
    }
    .btn-primary:hover { background: var(--red-dark); transform: translateY(-1px); }
    .btn-outline-white {
      background: transparent; color: var(--white);
      border-color: rgba(255,255,255,.7);
    }
    .btn-outline-white:hover { background: rgba(255,255,255,.15); }
    .btn-outline-navy {
      background: transparent; color: var(--navy);
      border-color: var(--navy);
    }
    .btn-outline-navy:hover { background: var(--navy); color: var(--white); }
    .section-label {
      display: inline-block; font-size: .75rem; font-weight: 700;
      letter-spacing: .12em; text-transform: uppercase;
      color: var(--red); margin-bottom: 12px;
    }
    .section-heading {
      font-size: clamp(1.6rem, 3vw, 2.4rem); font-weight: 800;
      color: var(--gray-900); line-height: 1.2; margin-bottom: 16px;
    }
    .section-sub {
      font-size: 1.05rem; color: var(--gray-600);
      max-width: 640px; line-height: 1.7;
    }
    .visually-hidden {
      position: absolute; width: 1px; height: 1px;
      overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap;
    }

    /* ── Utility bar ────────────────────────────────────────── */
    #utility-bar {
      background: var(--navy-dark);
      color: rgba(255,255,255,.8);
      font-size: .8rem;
      padding: 6px 0;
    }
    #utility-bar .container {
      display: flex; justify-content: flex-end; gap: 20px; align-items: center;
    }
    #utility-bar a:hover { color: var(--white); }

    /* ── Header ─────────────────────────────────────────────── */
    #site-header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky; top: 0; z-index: 500;
      box-shadow: var(--shadow-sm);
    }
    #site-header .container {
      display: flex; align-items: center;
      height: 70px; gap: 40px;
    }
    .logo {
      display: flex; align-items: center; gap: 12px;
      flex-shrink: 0;
    }
    .logo-icon {
      width: 44px; height: 44px; border-radius: 50%;
      background: var(--red);
      display: flex; align-items: center; justify-content: center;
      color: var(--white); font-weight: 800; font-size: 1.1rem;
      flex-shrink: 0;
    }
    .logo-text { display: flex; flex-direction: column; line-height: 1.1; }
    .logo-text strong { font-size: .95rem; font-weight: 800; color: var(--navy); }
    .logo-text span { font-size: .72rem; color: var(--gray-600); letter-spacing: .04em; }

    #main-nav { flex: 1; }
    #main-nav ul {
      display: flex; list-style: none; gap: 4px; align-items: center;
    }
    #main-nav a {
      font-size: .875rem; font-weight: 500; color: var(--gray-800);
      padding: 6px 10px; border-radius: var(--radius);
      transition: color var(--transition), background var(--transition);
    }
    #main-nav a:hover { color: var(--red); background: var(--red-light); }
    #main-nav .nav-donate {
      background: var(--red); color: var(--white);
      padding: 8px 18px; font-weight: 700;
      border-radius: var(--radius);
    }
    #main-nav .nav-donate:hover { background: var(--red-dark); color: var(--white); }

    .hamburger {
      display: none; background: none; border: none;
      padding: 8px; margin-left: auto;
      color: var(--gray-800);
    }
    .hamburger svg { display: block; }

    /* Mobile drawer */
    #mobile-menu {
      display: none; flex-direction: column;
      background: var(--white);
      border-top: 1px solid var(--gray-200);
      padding: 16px 24px 24px;
      gap: 4px;
    }
    #mobile-menu.open { display: flex; }
    #mobile-menu a {
      display: block; padding: 10px 12px;
      font-size: .95rem; font-weight: 500; color: var(--gray-800);
      border-radius: var(--radius);
    }
    #mobile-menu a:hover { background: var(--gray-50); color: var(--red); }
    #mobile-menu .mobile-donate {
      margin-top: 8px; display: block;
      background: var(--red); color: var(--white) !important;
      text-align: center; font-weight: 700; padding: 12px;
    }

    /* ── Hero ───────────────────────────────────────────────── */
    #hero {
      position: relative; overflow: hidden;
      min-height: 580px;
      display: flex; align-items: center;
      background: linear-gradient(135deg, var(--navy-dark) 0%, #0f2035 60%, #1a1a2e 100%);
      color: var(--white);
    }
    #hero::before {
      content: '';
      position: absolute; inset: 0;
      background: url('https://images.unsplash.com/photo-1578357078586-491adf1aa5ba?w=1600&q=70') center/cover no-repeat;
      opacity: .18;
    }
    .hero-content {
      position: relative; z-index: 1;
      max-width: 680px;
      padding: 80px 0;
    }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: var(--red); color: var(--white);
      font-size: .78rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
      padding: 5px 14px; border-radius: 100px; margin-bottom: 24px;
    }
    .hero-badge::before {
      content: '';
      width: 8px; height: 8px; border-radius: 50%;
      background: rgba(255,255,255,.85);
      animation: pulse-dot 2s infinite;
    }
    @keyframes pulse-dot {
      0%,100% { opacity: 1; transform: scale(1); }
      50% { opacity: .5; transform: scale(.8); }
    }
    #hero h1 {
      font-size: clamp(2rem, 5vw, 3.2rem); font-weight: 800;
      line-height: 1.12; margin-bottom: 20px;
    }
    #hero h1 span { color: #e87a8a; }
    #hero p {
      font-size: 1.1rem; color: rgba(255,255,255,.85);
      max-width: 560px; line-height: 1.7; margin-bottom: 36px;
    }
    .hero-actions { display: flex; gap: 14px; flex-wrap: wrap; }
    .hero-actions .btn { min-width: 160px; font-size: 1.05rem; padding: 14px 32px; }

    /* ── Mission ────────────────────────────────────────────── */
    #mission { padding: 80px 0; background: var(--white); }
    .mission-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .mission-visual {
      border-radius: 12px; overflow: hidden;
      box-shadow: var(--shadow-lg); position: relative;
    }
    .mission-visual img {
      width: 100%; height: 360px; object-fit: cover;
    }
    .mission-year {
      position: absolute; bottom: 20px; left: 20px;
      background: var(--red); color: var(--white);
      font-weight: 800; font-size: .85rem; padding: 6px 14px;
      border-radius: var(--radius);
    }
    .mission-text blockquote {
      border-left: 4px solid var(--red); padding-left: 20px;
      margin: 24px 0; font-style: italic; color: var(--gray-600);
      font-size: 1rem; line-height: 1.7;
    }
    .mission-text p { color: var(--gray-700); line-height: 1.8; margin-bottom: 16px; }
    .mission-principles {
      display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px;
    }
    .principle-chip {
      background: var(--red-light); color: var(--red);
      font-size: .8rem; font-weight: 700;
      padding: 6px 14px; border-radius: 100px;
    }

    /* ── Impact Stats ───────────────────────────────────────── */
    #impact { background: var(--navy); color: var(--white); padding: 70px 0; }
    #impact .section-heading { color: var(--white); text-align: center; }
    .stats-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px;
      margin-top: 48px;
      border: 1px solid rgba(255,255,255,.12);
      border-radius: 12px; overflow: hidden;
    }
    .stat-card {
      padding: 40px 28px; text-align: center;
      background: rgba(255,255,255,.04);
      transition: background var(--transition);
    }
    .stat-card:hover { background: rgba(255,255,255,.09); }
    .stat-number {
      font-size: clamp(2rem, 4vw, 3rem); font-weight: 800;
      color: var(--white); line-height: 1; margin-bottom: 8px;
    }
    .stat-number .count { color: #e87a8a; }
    .stat-unit { color: rgba(255,255,255,.65); font-size: .85rem; font-weight: 600; letter-spacing: .04em; }
    .stat-label { font-size: .95rem; color: rgba(255,255,255,.75); margin-top: 6px; }
    .stats-note {
      text-align: center; margin-top: 32px;
      color: rgba(255,255,255,.55); font-size: .875rem;
    }

    /* ── Programs accordion ─────────────────────────────────── */
    #programs { padding: 80px 0; background: var(--gray-50); }
    .programs-layout {
      display: grid; grid-template-columns: 5fr 4fr; gap: 60px; margin-top: 48px; align-items: start;
    }
    .accordion { border-radius: 10px; overflow: hidden; box-shadow: var(--shadow-sm); }
    .accordion-item { background: var(--white); border-bottom: 1px solid var(--gray-200); }
    .accordion-item:last-child { border-bottom: none; }
    .accordion-btn {
      width: 100%; background: none; border: none;
      display: flex; align-items: center; justify-content: space-between;
      padding: 20px 24px; text-align: left;
      font-size: 1rem; font-weight: 700; color: var(--gray-900);
      transition: background var(--transition), color var(--transition);
      gap: 12px;
    }
    .accordion-btn:hover { background: var(--gray-50); color: var(--red); }
    .accordion-btn.active { color: var(--red); background: var(--red-light); }
    .accordion-icon {
      width: 28px; height: 28px; flex-shrink: 0;
      border-radius: 50%; background: var(--red-light);
      display: flex; align-items: center; justify-content: center;
      color: var(--red); font-size: .75rem; font-weight: 800;
      transition: background var(--transition), color var(--transition), transform var(--transition);
    }
    .accordion-btn.active .accordion-icon {
      background: var(--red); color: var(--white); transform: rotate(45deg);
    }
    .accordion-body {
      max-height: 0; overflow: hidden;
      transition: max-height .35s ease, padding .3s ease;
      padding: 0 24px;
    }
    .accordion-body.open { max-height: 300px; padding: 0 24px 20px; }
    .accordion-body p { color: var(--gray-600); font-size: .95rem; line-height: 1.75; }
    .accordion-body .learn-more {
      display: inline-block; margin-top: 12px;
      font-size: .875rem; font-weight: 700; color: var(--red);
    }
    .accordion-body .learn-more:hover { text-decoration: underline; }
    .programs-aside { position: sticky; top: 90px; }
    .programs-aside img {
      border-radius: 12px; height: 300px; width: 100%; object-fit: cover;
      box-shadow: var(--shadow);
    }
    .programs-callout {
      background: var(--navy); color: var(--white);
      border-radius: 10px; padding: 28px 24px; margin-top: 20px;
    }
    .programs-callout h3 { font-size: 1.1rem; font-weight: 700; margin-bottom: 8px; }
    .programs-callout p { font-size: .9rem; color: rgba(255,255,255,.75); line-height: 1.65; margin-bottom: 16px; }
    .programs-callout .btn { width: 100%; }

    /* ── Get Involved ───────────────────────────────────────── */
    #get-involved { padding: 80px 0; background: var(--white); }
    .involve-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; margin-top: 48px;
    }
    .involve-card {
      border: 1px solid var(--gray-200); border-radius: 12px;
      padding: 32px 28px; text-align: center;
      transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
    }
    .involve-card:hover {
      box-shadow: var(--shadow); transform: translateY(-4px);
      border-color: var(--red);
    }
    .involve-icon {
      width: 64px; height: 64px; margin: 0 auto 20px;
      border-radius: 50%; background: var(--red-light);
      display: flex; align-items: center; justify-content: center;
      font-size: 1.8rem;
    }
    .involve-card h3 { font-size: 1.15rem; font-weight: 700; color: var(--navy); margin-bottom: 12px; }
    .involve-card p { font-size: .9rem; color: var(--gray-600); line-height: 1.7; margin-bottom: 24px; }
    .involve-card .btn { width: 100%; }

    /* ── News Carousel ──────────────────────────────────────── */
    #news { padding: 80px 0; background: var(--gray-50); }
    .news-header {
      display: flex; align-items: flex-end; justify-content: space-between;
      margin-bottom: 40px; gap: 20px; flex-wrap: wrap;
    }
    .carousel-controls { display: flex; gap: 10px; }
    .carousel-btn {
      width: 44px; height: 44px; border-radius: 50%;
      border: 2px solid var(--gray-200); background: var(--white);
      color: var(--gray-800); font-size: 1.1rem;
      display: flex; align-items: center; justify-content: center;
      transition: background var(--transition), border-color var(--transition), color var(--transition);
    }
    .carousel-btn:hover { background: var(--red); border-color: var(--red); color: var(--white); }
    .carousel-btn:focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }
    .carousel-viewport { overflow: hidden; }
    .carousel-track {
      display: flex; gap: 24px;
      transition: transform .45s ease;
    }
    .news-card {
      flex: 0 0 calc(33.33% - 16px); background: var(--white);
      border-radius: 12px; overflow: hidden;
      box-shadow: var(--shadow-sm); border: 1px solid var(--gray-200);
      transition: box-shadow var(--transition), transform var(--transition);
    }
    .news-card:hover { box-shadow: var(--shadow); transform: translateY(-3px); }
    .news-card-img {
      width: 100%; height: 200px; object-fit: cover;
      background: var(--gray-200);
    }
    .news-card-body { padding: 22px; }
    .news-tag {
      display: inline-block; background: var(--red-light); color: var(--red);
      font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em;
      padding: 3px 10px; border-radius: 100px; margin-bottom: 10px;
    }
    .news-card h3 { font-size: 1rem; font-weight: 700; color: var(--gray-900); margin-bottom: 8px; line-height: 1.35; }
    .news-card p { font-size: .875rem; color: var(--gray-600); line-height: 1.65; }
    .news-card-link {
      display: inline-block; margin-top: 14px;
      font-size: .875rem; font-weight: 700; color: var(--red);
    }
    .news-card-link:hover { text-decoration: underline; }
    .carousel-dots {
      display: flex; justify-content: center; gap: 8px; margin-top: 28px;
    }
    .dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: var(--gray-300); border: none;
      transition: background var(--transition), transform var(--transition);
    }
    .dot.active { background: var(--red); transform: scale(1.3); }

    /* ── Donate CTA ─────────────────────────────────────────── */
    #donate-cta { padding: 80px 0; background: var(--white); }
    .donate-inner {
      background: linear-gradient(135deg, var(--navy) 0%, #0f2035 100%);
      border-radius: 16px; padding: 64px 56px;
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
      position: relative; overflow: hidden;
    }
    .donate-inner::before {
      content: ''; position: absolute;
      right: -60px; top: -60px;
      width: 300px; height: 300px; border-radius: 50%;
      background: rgba(196,30,58,.15);
    }
    .donate-inner::after {
      content: ''; position: absolute;
      left: -40px; bottom: -80px;
      width: 220px; height: 220px; border-radius: 50%;
      background: rgba(255,255,255,.04);
    }
    .donate-copy { position: relative; z-index: 1; }
    .donate-copy .section-label { color: #e87a8a; }
    .donate-copy .section-heading { color: var(--white); }
    .donate-copy p { color: rgba(255,255,255,.78); font-size: .95rem; line-height: 1.75; }
    .donate-copy .efficiency {
      display: flex; align-items: center; gap: 12px;
      margin-top: 24px; padding: 14px 18px;
      background: rgba(255,255,255,.08); border-radius: 8px;
    }
    .efficiency-pct {
      font-size: 1.8rem; font-weight: 800; color: #e87a8a; flex-shrink: 0; line-height: 1;
    }
    .efficiency-text { font-size: .85rem; color: rgba(255,255,255,.75); line-height: 1.5; }

    .donate-amounts { position: relative; z-index: 1; }
    .amounts-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 20px; }
    .amount-btn {
      background: rgba(255,255,255,.08); color: var(--white);
      border: 2px solid rgba(255,255,255,.2);
      border-radius: 8px; padding: 14px 16px;
      font-size: .9rem; font-weight: 600; text-align: center;
      transition: background var(--transition), border-color var(--transition);
      line-height: 1.3;
    }
    .amount-btn .amt { font-size: 1.25rem; font-weight: 800; display: block; }
    .amount-btn .impact { font-size: .75rem; color: rgba(255,255,255,.6); display: block; margin-top: 4px; }
    .amount-btn:hover, .amount-btn.selected {
      background: var(--red); border-color: var(--red);
    }
    .amounts-grid .amount-btn.custom { grid-column: 1 / -1; }
    .donate-now-btn {
      width: 100%; padding: 16px; font-size: 1.05rem; font-weight: 700;
      background: var(--red); color: var(--white); border: none;
      border-radius: 8px; transition: background var(--transition), transform var(--transition);
    }
    .donate-now-btn:hover { background: var(--red-dark); transform: translateY(-1px); }
    .donate-secure {
      display: flex; align-items: center; justify-content: center; gap: 6px;
      margin-top: 12px; font-size: .78rem; color: rgba(255,255,255,.5);
    }

    /* ── Footer ─────────────────────────────────────────────── */
    #site-footer { background: var(--gray-900); color: rgba(255,255,255,.75); padding: 60px 0 0; }
    .footer-top {
      display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 40px;
      padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,.1);
    }
    .footer-brand { }
    .footer-logo { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
    .footer-logo-icon {
      width: 40px; height: 40px; border-radius: 50%; background: var(--red);
      display: flex; align-items: center; justify-content: center;
      color: var(--white); font-weight: 800; font-size: 1rem; flex-shrink: 0;
    }
    .footer-logo-text strong { font-size: .9rem; font-weight: 700; color: var(--white); display: block; }
    .footer-logo-text span { font-size: .7rem; color: rgba(255,255,255,.45); }
    .footer-brand p { font-size: .875rem; line-height: 1.7; max-width: 260px; margin-bottom: 20px; }
    .social-links { display: flex; gap: 10px; }
    .social-link {
      width: 36px; height: 36px; border-radius: 50%;
      background: rgba(255,255,255,.08);
      display: flex; align-items: center; justify-content: center;
      font-size: .8rem; font-weight: 700; color: rgba(255,255,255,.7);
      transition: background var(--transition), color var(--transition);
    }
    .social-link:hover { background: var(--red); color: var(--white); }

    .footer-col h4 {
      font-size: .8rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
      color: var(--white); margin-bottom: 16px;
    }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-col a { font-size: .875rem; color: rgba(255,255,255,.6); transition: color var(--transition); }
    .footer-col a:hover { color: var(--white); }

    .footer-bottom {
      padding: 20px 0;
      display: flex; justify-content: space-between; align-items: center;
      flex-wrap: wrap; gap: 12px; font-size: .8rem;
      color: rgba(255,255,255,.35);
    }
    .footer-bottom a { color: rgba(255,255,255,.45); }
    .footer-bottom a:hover { color: rgba(255,255,255,.8); }
    .footer-bottom-links { display: flex; gap: 16px; }
    .tax-id { background: rgba(255,255,255,.06); padding: 3px 10px; border-radius: var(--radius); }

    /* ── Donation Modal ─────────────────────────────────────── */
    #donate-modal {
      display: none; position: fixed; inset: 0; z-index: 900;
      align-items: center; justify-content: center;
    }
    #donate-modal.open { display: flex; }
